style.css:
@-moz-document domain("roblox.com") {
/* --- Base background on html & body --- */
  html, body {
    background: #0a0a0a !important;
  }

  /* --- Fixed background image layer behind everything --- */
  body::before {
    content: "" !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background-image: url('https://i.imgur.com/yWPNpL9.jpg') !important;
    /* ^ If the above doesn't show, try: https://i.imgur.com/yWPNpL9.png */
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    z-index: -9999 !important;
    pointer-events: none !important;
  }

  /* --- Dark overlay so text stays readable --- */
  body::after {
    content: "" !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background: rgba(10, 5, 15, 0.55) !important;
    z-index: -9998 !important;
    pointer-events: none !important;
  }

  /* --- Make Roblox's main content areas semi-transparent
         so the background shows through --- */
  #container-main,
  .content,
  .rbx-content,
  .game-main-content,
  .profile-container,
  .home-container,
  .avatar-container,
  .catalog-container,
  .message-container,
  [class*="content"],
  [class*="container"] {
    background-color: rgba(20, 20, 30, 0.75) !important;
    backdrop-filter: blur(4px) !important;
  }

  /* --- Force dark text backgrounds to be transparent-ish --- */
  .rbx-header,
  .navigation,
  .dark-theme,
  .light-theme {
    background-color: rgba(15, 15, 25, 0.85) !important;
  }

  /* --- Sidebar & panels --- */
  .rbx-left-col,
  .rbx-right-col,
  .menu-vertical,
  .section,
  .tab-content,
  .card,
  .item-card-container,
  .game-card-container {
    background-color: rgba(25, 25, 35, 0.7) !important;
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
  }

  /* --- Text readability fix --- */
  h1, h2, h3, h4, h5, h6,
  p, span, a, div,
  .text-name,
  .text-label,
  .text-title,
  .text-description {
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8) !important;
  }
}
